def max_water_trapped(heights):
    left = 0
    right = len(heights) - 1
    max_area = 0

    while left < right:
        if heights[left] <= heights[right]:
            width = right - left
            max_area = max(max_area, width * heights[left])
            left += 1
        else:
            width = right - left
            max_area = max(max_area, width * heights[right])
            right -= 1

    return max_area
```

